-- Get current sequence values
DO $$ 
DECLARE
    citizen_seq INTEGER;
    agriculture_seq INTEGER;
    income_seq INTEGER;
BEGIN
    SELECT COALESCE(MAX(citizen_id), 0) + 1 INTO citizen_seq FROM "Citizen";
